import{az as r,P as a,Q as n,aQ as o}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const p=JSON.parse('{"title":"设计模式与编程思想","description":"","frontmatter":{},"headers":[],"relativePath":"设计模式/index.md","filePath":"设计模式/index.md","lastUpdated":1785251536000}'),e={name:"设计模式/index.md"};function i(s,t,l,d,g,h){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="设计模式与编程思想" tabindex="-1">设计模式与编程思想 <a class="header-anchor" href="#设计模式与编程思想" aria-label="Permalink to “设计模式与编程思想”">​</a></h1><h2 id="编程思想-编程范式" tabindex="-1">编程思想（编程范式） <a class="header-anchor" href="#编程思想-编程范式" aria-label="Permalink to “编程思想（编程范式）”">​</a></h2><p>编程思想是编写代码的<strong>宏观方法论</strong>，决定了代码的整体组织方式和思维模式：</p><ul><li><strong>函数式编程</strong>：以纯函数为核心，强调无副作用、不可变数据</li><li><strong>面向过程编程</strong>：以步骤和函数为核心，自顶向下分解问题</li><li><strong>面向对象编程</strong>：以对象为核心，封装数据和行为，通过继承和多态实现复用</li><li><strong>高阶函数</strong>：函数作为参数或返回值，是函数式编程的重要技术手段</li><li><strong>hooks</strong>：将状态逻辑从组件中抽离，实现逻辑复用</li><li><strong>闭包</strong>：函数访问其外部作用域变量的能力，是许多模式的基础</li><li><strong>柯里化</strong>：将多参数函数转为单参数函数链，提升函数灵活性</li></ul><h2 id="设计模式" tabindex="-1">设计模式 <a class="header-anchor" href="#设计模式" aria-label="Permalink to “设计模式”">​</a></h2><p>设计模式是解决<strong>特定场景下常见问题</strong>的成熟方案，是编程思想的具体落地实践：</p><ul><li><strong>工厂模式</strong>：统一管理对象创建，解耦调用方与具体类</li><li><strong>单例模式</strong>：确保一个类只有一个实例，提供全局访问点</li><li><strong>发布订阅模式</strong>：通过事件中心解耦发送者和接收者</li><li><strong>观察者模式</strong>：一对多依赖关系，当对象状态变化时通知所有依赖</li></ul><h2 id="关系" tabindex="-1">关系 <a class="header-anchor" href="#关系" aria-label="Permalink to “关系”">​</a></h2><p>编程思想是&quot;道&quot;，设计模式是&quot;术&quot;。理解编程思想能让你写出更优雅的代码，掌握设计模式能让你解决具体的工程问题。</p>',9)])])}const m=r(e,[["render",i]]);export{p as __pageData,m as default};
